result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/app.py", "content": """"Internal reporting service with API-key authentication."""
import json
import os

from flask import Flask, jsonify, request

app = Flask(__name__)

KEYS_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "keys.json")


def load_valid_keys():
    """Read the list of valid API keys from keys.json."""
    with open(KEYS_FILE, "r", encoding="utf-8") as f:
        return set(json.load(f))


def require_api_key(func):
    """Decorator enforcing X-API-Key auth.

    - Missing header -> 401
    - Unknown key    -> 403
    - Valid key      -> passes through to the wrapped view
    """

    from functools import wraps

    @wraps(func)
    def wrapper(*args, **kwargs):
        api_key = request.headers.get("X-API-Key")
        if not api_key:
            return jsonify({"error": "Missing X-API-Key header"}), 401
        if api_key not in load_valid_keys():
            return jsonify({"error": "Invalid API key"}), 403
        return func(*args, **kwargs)

    return wrapper


@app.get("/secret")
@require_api_key
def secret():
    return jsonify({"data": "classified"})


if __name__ == "__main__":
    app.run(port=5000)
